// ============================================================
// Tc2_Math.stLibVersion_Tc2_Math 演示程序
// ============================================================
// 注意：项目须引用 Tc2_Math 与 Tc2_System（提供 ST_LibVersion / F_CmpLibVersion）
// 验证步骤：
//   1. 编译 + 登录
//   2. 在线监视 stMyVer 应显示 1.3.3
//   3. 在线监视 bOk 应为 TRUE
// ============================================================

stMyVer := stLibVersion_Tc2_Math;

bOk := F_CmpLibVersion(
    stLibVersion := stLibVersion_Tc2_Math,
    iMajor := 1, iMinor := 3, iBuild := 3, iRevision := 0,
    nCmpType := E_CmpLibVersion.GreaterOrEqual
);
